@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class CreativeEmployee extends Employee {
  + hasOscar : boolean
}

class Director extends CreativeEmployee {
  + assistantName : string
}

class Actor extends CreativeEmployee {
  + education : string
}

class Technician extends Employee {
  + fieldOfActivity : string
}

class FilmSet {
  + location : string
}

class Film {
  + title : string
  + releaseYear : int
}

class Genre {
  + type : string
}

class Screenwriter {
  + name : string
  + mostSuccessfulFilm : string
}

class Screenplay {
  + title : string
  + version : string
  + date : date
  + numberOfScenes : int
  + plot : string
}

class Novel {
  + title : string
  + author : string
}

class Concept {
}

FilmSet "*" -- "*" Film : used for
Film "*" -- "1" Genre : assigned to
Film "1" -- "1" Screenplay : based on
Screenplay "1" -- "1" Screenwriter : written by
Screenplay "0..1" -- "1" Novel : based on
Screenplay "0..1" -- "1" Concept : based on
Actor "1..*" -- "1" Screenplay : reads
Director "1" -- "1" Screenplay : implements

@enduml

